```python
def parse(text: str):
    """parse — kratak opis namjene funkcije.

Args:
    text: opis argumenta.

Returns:
    Rezultat obrade.
"""
    m = FUNC_RE.search(text or '')
    if not m:
        return (None, None)
    args: dict = {}
    import re as _re
    for k, v in _re.findall('<parameter=([a-z_][a-z0-9_]*)>(.*?)</parameter>', text, _re.IGNORECASE | _re.DOTALL):
        v = v.strip()
        args[k] = int(v) if k in INT_ARGS and v.isdigit() else v
    return (m.group(1), args)
```

