def typo(s: str) -> str:
    fix = {"nginx": "ngnix", "apache2": "apace2", "postgresql": "postresql",
           "mysql": "myslq", "docker": "dokcer", "redis": "rediss"}
    if s in fix:
        return fix[s]
    if len(s) >= 4:
        i = len(s) // 2
        t = s[:i] + s[i + 1] + s[i] + s[i + 2:]
        return t if t != s else s + "x"  # shortcut: isto slovo na obje pozicije (npr. caddy)
    return s + "x"
```

